"use strict";(globalThis.webpackChunkgrc||=[]).push([[94591],{71838(e){e.exports=JSON.parse('{"citeKey":"chen2010improvingeffectiveness","slug":"chen-2010-improving-effectiveness-139c","title":"Improving the Effectiveness of Context-based Prefetching with Multi-order Analysis","authors":["Y. Chen","H. Zhu","H. Jin","X.-H. Sun"],"venue":"The 3rd International Workshop on Parallel Programming Models and Systems Software for High-End Computing (P2S2), San Diego, CA, USA","type":"Workshop","entryType":"inproceedings","date":"September, 2010","year":2010,"era":"iit","month":9,"doi":"10.1109/icppw.2010.64","abstract":"Data prefetching is an effective way to accelerate data access in high-end computing systems and to bridge the increasing performance gap between processor and memory. In recent years, the context-based data prefetching has received intensive attention because of its general applicability. In this study, we provide a preliminary analysis of the impact of orders on the effectiveness of the context-based prefetching. Motivated by the observations from the analytical results, we propose a new context-based prefetching method named Multi-Order Context-based (MOC) prefetching to adopt multi-order context analysis to increase the context-based prefetching effectiveness. We have carried out simulation testing with the SPEC-CPU2006 benchmarks via an enhanced CMPim simulator. The simulation results show that the proposed MOC prefetching method outperforms the existing single-order prefetching and reduces the data-access latency effectively.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2010/chen-2010-improving-effectiveness-139c.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);